import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick }) {
  const menuItems = [
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' },
  ];

  return (
    <div style={{ 
      width: '260px', 
      backgroundColor: '#15803d', 
      color: '#ffffff', 
      padding: '25px 15px', 
      display: 'flex', 
      flexDirection: 'column', 
      boxSizing: 'border-box',
      minHeight: '100%'
    }}>
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <div style={{ padding: '0 15px 10px 15px' }}>
          <span style={{ fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.5px' }}>📌 Admin Panel</span>
        </div>

        {/* මෙන්න Admin Panel එකට යටින්ම සෙට් කරපු ලොකු Logout බටන් එක */}
        <div 
          onClick={onLogoutClick}
          style={{ 
            padding: '12px 18px', 
            borderRadius: '8px', 
            cursor: 'pointer', 
            display: 'flex', 
            justifyContent: 'center',
            alignItems: 'center', 
            gap: '10px', 
            backgroundColor: '#dc2626', 
            fontWeight: 'bold',
            fontSize: '14px',
            marginBottom: '25px',
            marginTop: '5px',
            boxShadow: '0 4px 10px rgba(0,0,0,0.1)'
          }}
        >
          <span>🚪</span> 
          <span>Logout</span>
        </div>

        <div style={{ borderTop: '1px solid rgba(255,255,255,0.15)', paddingTop: '15px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {menuItems.map((item, i) => {
            const isActive = currentSubPage === item.name;
            return (
              <div 
                key={i} 
                onClick={() => setCurrentSubPage(item.name)}
                style={{ 
                  padding: '14px 18px', 
                  borderRadius: '8px', 
                  cursor: 'pointer', 
                  display: 'flex', 
                  alignItems: 'center', 
                  gap: '12px', 
                  backgroundColor: isActive ? '#166534' : 'transparent', 
                  fontWeight: isActive ? '700' : '500',
                  transition: 'all 0.2s'
                }}
              >
                <span style={{ fontSize: '16px' }}>{item.icon}</span> 
                <span style={{ fontSize: '14px' }}>{item.name}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
